<div class="edit-columns"><div><section class="admin-panel neu-flat"><h2>L’essentiel</h2><label>Nom du succès<input name="name" maxlength="191" required value="<?= e($item['name'] ?? '') ?>"></label><label>Slug unique<input name="slug" pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="191" required value="<?= e($item['slug'] ?? '') ?>"><span class="form-help">Exemple : le-destin-dans-la-poche. Utilisé dans l’URL publique.</span></label><label>Description<textarea name="description" rows="5" maxlength="12000"><?= e($item['description'] ?? '') ?></textarea></label><label>Conditions de déblocage<textarea name="unlock_conditions" rows="5" maxlength="12000"><?= e($item['unlock_conditions'] ?? '') ?></textarea></label></section>
<section class="admin-panel neu-flat"><h2>Récompenses</h2><div class="form-grid"><?php foreach (App\Services\CatalogService::REWARDS as $field=>$label): ?><label><?= e($label) ?><input name="<?= e($field) ?>" inputmode="numeric" pattern="[0-9]*" maxlength="20" placeholder="Inconnu" value="<?= e($item[$field] ?? '') ?>"></label><?php endforeach; ?></div><fieldset class="title-options"><legend>Titres associés</legend><?php if (!$titles): ?><p class="form-help">Aucun titre disponible. Un administrateur peut en créer dans la rubrique Titres.</p><?php endif; ?><?php foreach ($titles as $title): ?><label class="check-label"><input type="checkbox" name="title_ids[]" value="<?= $title['id'] ?>" <?= in_array((int)$title['id'],$item['title_ids'] ?? [],true)?'checked':'' ?>><?= e($title['name']) ?></label><?php endforeach; ?></fieldset><label class="check-label"><input type="checkbox" name="title_rewards_known" value="1" <?= !empty($item['title_rewards_known'])?'checked':'' ?>>La liste des titres est connue (vide = aucun titre)</label></section>
