<aside><section class="admin-panel neu-flat"><h2>Classement</h2><label>Catégorie<select name="category_id"><option value="">Non renseignée</option><?php foreach ($categories as $category): if ($category['archived_at']) continue; ?><option value="<?= $category['id'] ?>" <?= (string)($item['category_id'] ?? '')===(string)$category['id']?'selected':'' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></label><label>Rareté<select name="rarity"><?php foreach ([''=>'Non renseignée','Commun'=>'Commun','Rare'=>'Rare','Épique'=>'Épique','Légendaire'=>'Légendaire'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= ($item['rarity'] ?? '')===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Type<select name="secret_type"><option value="normal" <?= ($item['secret_type'] ?? '')==='normal'?'selected':'' ?>>Classique</option><option value="secret" <?= ($item['secret_type'] ?? '')==='secret'?'selected':'' ?>>Secret</option></select></label></section><section class="admin-panel neu-flat"><h2>Publication</h2><label>Vérification<select name="verification_status"><?php foreach (['unverified'=>'À confirmer','pending'=>'En cours de vérification','verified'=>'Confirmé','rejected'=>'Information rejetée'] as $value=>$label): ?><option value="<?= $value ?>" <?= ($item['verification_status'] ?? 'unverified')===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Visibilité<select name="publication_status"><option value="draft" <?= ($item['publication_status'] ?? 'draft')==='draft'?'selected':'' ?>>Brouillon — privé</option><option value="published" <?= ($item['publication_status'] ?? '')==='published'?'selected':'' ?>>Publié — visible au public</option></select></label><p class="form-help">La vérification et la publication sont indépendantes. Seuls les succès publiés et non archivés sont publics.</p><button class="primary-button">Enregistrer le succès</button></section></aside></div></form>
<?php if ($editing && App\Services\PermissionService::admin($user)): ?><section class="admin-panel danger-panel"><h2>Cycle de vie</h2><details><summary>Archiver, restaurer ou supprimer</summary><p class="form-help">L’archivage retire le succès du site public. La restauration rétablit sa visibilité précédente. La suppression efface le succès et sa capture, mais conserve l’historique.</p><?php foreach ([$item['archived_at']?'restore':'archive'=>'Archiver / restaurer', 'delete'=>'Supprimer définitivement'] as $action=>$label): if ($action==='delete' && !App\Services\PermissionService::owner($user)) continue; ?><form method="post" action="/admin/achievements/<?= $item['id'] ?>/<?= $action ?>" class="danger-form"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><label class="check-label"><input type="checkbox" name="confirm" value="1" required>Je confirme cette opération</label><button class="secondary-button <?= $action==='delete'?'danger-button':'' ?>"><?= $action==='archive'?'Archiver':($action==='restore'?'Restaurer':$label) ?></button></form><?php endforeach; ?></details></section><?php endif; ?>
